这道问题可以通过数学方法，利用排列的结构和字典序来确定第 $k$ 个排列，而不需要生成所有排列。

核心思路是：在每一步（确定一个数字）中，我们计算当前剩余数字的排列总数。这个总数决定了第 $k$ 个排列的第一个数字应该落在哪个“块”中。

1. **预处理**：计算 $0!$ 到 $(n-1)!$ 的阶乘。
2. **初始化**：创建一个包含数字 $1$ 到 $n$ 的列表（可变），并初始化结果字符串。
3. **迭代**：从 $i=n$ 递减到 $1$（确定 $n$ 个位置）。
    a. 计算当前块的大小 $fact = (i-1)!$。
    b. **确定索引**：由于 $k$ 是 1-based 索引，我们计算该数字在当前可用列表中的索引 $idx = \lfloor (k - 1) / fact \rfloor$。
    c. **确定数字**：将可用列表中的第 $idx$ 个数字添加到结果中。
    d. **更新列表**：从可用列表中移除该数字。
    e. **更新 $k$**：将 $k$ 调整到该数字块内的相对位置：$k = (k - 1) \pmod{fact} + 1$。

### C++ 实现

```cpp
#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <cmath>

using namespace std;

class Solution {
public:
    string getPermutation(int n, int k) {
    // 1. 预计算阶乘 (N <= 9, 整数足够)
    vector<int> factorials(n + 1);
    factorials[0] = 1;
    for (int i = 1; i <= n; ++i) {
        factorials[i] = factorials[i - 1] * i;
    }

    // 2. 初始化可用数字列表
    vector<int> nums;
    for (int i = 1; i <= n; ++i) {
        nums.push_back(i);
    }

    string result = "";

    // k 是 1-based 索引
    // 3. 迭代确定每个位置的数字
    for (int i = n; i >= 1; --i) {
        // 当前块的大小是 (i-1)!
        int fact = factorials[i - 1];

        // 确定当前数字在 nums 列表中的索引 (0-based)
        // k-1 是 0-based 偏移量
        int index = (k - 1) / fact;

        // 确定数字并添加到结果
        result += to_string(nums[index]);

        // 从可用列表中移除该数字
        nums.erase(nums.begin() + index);

        // 更新 k：将 k 调整到该块内的相对排名 (1-based)
        k = (k - 1) % fact + 1;
    }

    return result;
}

// 示例测试（可选）
/*
int main() {
    Solution s;

    // 示例 1: n = 3, k = 3 -> "213"
    cout << "N=3, K=3: " << s.getPermutation(3, 3) << endl; 

    // 示例 2: n = 4, k = 9 -> "2314"
    cout << "N=4, K=9: " << s.getPermutation(4, 9) << endl; 

    // 示例 3: n = 3, k = 1 -> "123"
    cout << "N=3, K=1: " << s.getPermutation(3, 1) << endl; 

    // 边界测试: n = 4, k = 24 (最大排列) -> "4321"
    cout << "N=4, K=24: " << s.getPermutation(4, 24) << endl; 

    return 0;
}
*/
```

