### 我的答案

利用字典序排列的分块结构：固定当前位置后，每个可选数字对应 \((r-1)!\) 个排列，其中 \(r\) 是剩余数字数。先将 \(k\) 转成从 0 开始的排名，再逐位确定数字。

```cpp
#include <string>
#include <vector>
using namespace std;

class Solution {
public:
    string getPermutation(int n, int k) {
        vector<int> fact(n, 1);
        for (int i = 1; i < n; ++i) {
            fact[i] = fact[i - 1] * i;
        }

        vector<int> nums;
        for (int i = 1; i <= n; ++i) {
            nums.push_back(i);
        }

        --k;  // 转成 0-based 排名
        string ans;
        for (int remaining = n; remaining >= 1; --remaining) {
            int index = k / fact[remaining - 1];
            ans += to_string(nums[index]);
            nums.erase(nums.begin() + index);
            k %= fact[remaining - 1];
        }
        return ans;
    }
};
```

