As an expert iOS developer, I recommend using the **MVVM (Model-View-ViewModel)** architectural pattern. This ensures a clear separation of concerns:

1.  **Model:** Defines the data structure (e.g., the path to the recorded file).
2.  **ViewModel:** Contains all the business logic (handling `AVFoundation`, managing state, implementing recording logic). It exposes `@Published` properties for the View to observe.
3.  **View:** Handles the UI presentation and delegates user actions to the ViewModel. It should contain minimal logic.

We will encapsulate the complex `AVFoundation` logic within the ViewModel to keep the View lightweight.

### 🛠️ Prerequisites (Info.plist)

Before running the code, you **must** add the following key to your `Info.plist` file, or the recording will fail due to permission denial:

*   **`Privacy - Microphone Usage Description`** (`NSMicrophoneUsageDescription`): Provide a user-facing string explaining *why* you need microphone access (e.g., "Needed to record your voice messages.").

### 📱 SwiftUI Code Implementation

#### 1. RecordingViewModel (The Logic Engine)

```swift
import SwiftUI
import AVFoundation
import Combine

// MARK: - ViewModel
class RecordingViewModel: ObservableObject {
    // State published to the SwiftUI View
    @Published var isRecording: Bool = false
    @Published var recordingFilePath: URL?
    @Published var recordingError: Error?

    // Internal AVFoundation components
    private var audioRecorder: AVAudioRecorder?
    private let audioSession = AVAudioSession.sharedInstance()

    // Configuration
    private let recordingFileName = "recording_\(UUID().uuidString).m4a"
    private var tempDirectory: URL {
        // Get the temporary directory for saving the file
        return FileManager.default.temporaryDirectory
    }

    init() {
        // Attempt to set up the audio session immediately
        setupAudioSession()
    }

    // MARK: - Setup
    private func setupAudioSession() {
        do {
            try audioSession.setCategory(.record, mode: .measurement, options: .defaultToPlayback)
            try audioSession.setActive(true)
        } catch {
            print("Error setting up audio session: \(error.localizedDescription)")
            recordingError = error
        }
    }

    // MARK: - Recording Control

    func startRecording() {
        guard !isRecording, recordingError == nil else { return }

        let fileURL = tempDirectory.appendingPathComponent(recordingFileName)

        do {
            let settings: [String: Any] = [
                AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
                AVSampleRateKey: 44100,
                AVNumberOfChannelsKey: 1,
                AVEncoderAudioQualityKey: AVAudioQuality.medium.rawValue
            ]

            audioRecorder = try AVAudioRecorder(url: fileURL, settings: settings)
            audioRecorder?.delegate = self
            audioRecorder?.prepareToRecord()
            audioRecorder?.record()

            DispatchQueue.main.async {
                self.isRecording = true
                self.recordingFilePath = fileURL
            }
        } catch {
            DispatchQueue.main.async {
                self.recordingError = error
                self.isRecording = false
            }
        }
    }

    func stopRecording() {
        guard isRecording, let recorder = audioRecorder else { return }

        recorder.stop()
        // The delegate method (audioRecorderDidFinishRecording) will handle the completion state
    }

    func saveAndFinishRecording() {
        // In a real app, you would move the file from the temp directory
        // to the application's Documents or a specific storage location.
        guard let path = recordingFilePath else {
            recordingError = NSError(domain: "Recording", code: 0, userInfo: [NSLocalizedDescriptionKey: "No recording file found."])
            return
        }

        // Simulate saving: Move file to a persistent location (e.g., Documents)
        let documentsURL = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
        let finalURL = documentsURL.appendingPathComponent(path.lastPathComponent)

        do {
            // Ensure parent directory exists
            try FileManager.default.createDirectory(at: documentsURL, withIntermediateDirectories: true, attributes: nil)
            // Move the file
            try FileManager.default.moveItem(at: path, to: finalURL)

            DispatchQueue.main.async {
                self.recordingFilePath = finalURL
                self.isRecording = false
                // Clear any previous errors
                self.recordingError = nil 
                print("✅ Recording successfully saved to: \(finalURL.path)")
            }
        } catch {
            DispatchQueue.main.async {
                self.recordingError = error
                print("❌ Error saving file: \(error.localizedDescription)")
            }
        }
    }
}

// MARK: - AVAudioRecorderDelegate
extension RecordingViewModel: AVAudioRecorderDelegate {
    func audioRecorderDidFinishRecording(_ recorder: AVAudioRecorder, successfully flag: Bool) {
        if flag {
            // Recording finished successfully (stop button pressed)
            DispatchQueue.main.async {
                self.isRecording = false
                // Note: The file is still in the temp directory until saveAndFinishRecording() is called.
            }
        } else {
            // Recording failed
            DispatchQueue.main.async {
                self.recordingError = NSError(domain: "Recording", code: 1, userInfo: [NSLocalizedDescriptionKey: "Recording failed."])
                self.isRecording = false
            }
        }
    }
}
```

#### 2. EqualizerVisualEffect (The UI Component)

This custom view uses SwiftUI's `TimelineView` and `Animatable` protocol to create a smooth, continuous, audio-like visualization without needing actual audio analysis.

```swift
import SwiftUI

struct EqualizerVisualEffect: View {
    @State private var amplitude: Double = 0.0 // Simulated amplitude 0.0 to 1.0

    var body: some View {
        ZStack {
            // The central visual element (The "equalizer" bar)
            VStack(spacing: 4) {
                ForEach(0..<8) { index in
                    Rectangle()
                        .fill(Color.blue.opacity(0.8))
                        .frame(width: 6, height: 30 + CGFloat(amplitude * (index % 2 == 0 ? 1 : 2))) // Amplitude drives height
                        .offset(y: CGFloat(index * 4))
                }
            }
            .scaleEffect(1.2)
            .animation(.easeInOut(duration: 0.1), value: amplitude) // Smooth animation
        }
        .onReceive(Timer.publish(every: 0.05, on: .main, in: .common).autoconnect()) { _ in
            // Simulate fluctuating audio input
            amplitude = Double.random(in: 0.4...1.0)
        }
    }
}
```

#### 3. ContentView (The View)

```swift
import SwiftUI

struct ContentView: View {
    // Use StateObject to manage the lifecycle of the ViewModel
    @StateObject private var viewModel = RecordingViewModel()

    var body: some View {
        VStack(spacing: 50) {

            // 1. Recording Indicator (Equalizer)
            if viewModel.isRecording {
                EqualizerVisualEffect()
                    .padding(.vertical, 50)
            } else {
                Text("Press Start to Record")
                    .font(.headline)
                    .foregroundColor(.gray)
            }

            // 2. Status/Feedback
            if let error = viewModel.recordingError {
                Text("Error: \(error.localizedDescription)")
                    .foregroundColor(.red)
                    .padding()
            } else if let path = viewModel.recordingFilePath {
                Text("Recording saved successfully!")
                    .foregroundColor(.green)
                    .font(.title2)
            }

            // 3. Control Buttons
            HStack(spacing: 40) {
                // Start Button
                Button {
                    viewModel.startRecording()
                } label: {
                    Text("Start Recording")
                        .frame(width: 150, height: 50)
                        .background(viewModel.isRecording ? Color.gray : Color.green)
                        .foregroundColor(.white)
                        .cornerRadius(10)
                }
                // Disable start button while recording
                .disabled(viewModel.isRecording)

                // Stop/Finish Button
                Button {
                    if viewModel.isRecording {
                        // Step 1: Stop the recording
                        viewModel.stopRecording()
                    } else {
                        // Step 2: Save the finished recording
                        viewModel.saveAndFinishRecording()
                    }
                } label: {
                    Text(viewModel.isRecording ? "Stop" : "Finish & Save")
                        .frame(width: 150, height: 50)
                        .background(viewModel.isRecording ? Color.red : Color.blue)
                        .foregroundColor(.white)
                        .cornerRadius(10)
                }
                // Disable if no recording has started or file is missing
                .disabled(!viewModel.isRecording && viewModel.recordingFilePath == nil)
            }
        }
        .padding()
        .onAppear {
            // Ensure audio session is ready when the view appears
            _ = viewModel
        }
    }
}
```

### 💡 Best Practices & Design Patterns Review

| Feature | Implementation | Best Practice/Pattern Used | Benefit |
| :--- | :--- | :--- | :--- |
| **Architecture** | MVVM (ViewModel handles logic, View handles UI) | Separation of Concerns | Testability, Maintainability, Scalability. |
| **State Management** | `@Published` and `@StateObject` | SwiftUI Observability | Clean, reactive UI updates without manual delegates. |
| **Audio Handling** | Dedicated `AVAudioRecorder` logic within ViewModel | Encapsulation | ViewModel is self-contained; View doesn't need `AVFoundation` knowledge. |
| **File Management** | Saving to `FileManager.default.temporaryDirectory` then moving to `Documents` | Safe Resource Handling | Ensures temporary files are cleaned up and final files are stored persistently. |
| **UI Feedback** | `EqualizerVisualEffect` using `Timer.publish` | Decoupled Visualization | The UI visualization is independent of the complex audio processing, keeping performance high. |
| **Concurrency** | `DispatchQueue.main.async` | Thread Safety | All UI state changes (`@Published`) happen on the main thread. |

This structure provides a robust, clean, and highly maintainable solution suitable for production-level iOS development.

