            ]

            let newRecorder = try AVAudioRecorder(url: temporaryURL, settings: settings)
            newRecorder.isMeteringEnabled = true
            newRecorder.prepareToRecord()
            guard newRecorder.record() else {
                throw NSError(domain: "VoiceRecorder", code: 1,
                              userInfo: [NSLocalizedDescriptionKey: "Could not start recording."])
            }

            recorder = newRecorder
            isRecording = true
            meterTimer = Timer.scheduledTimer(withTimeInterval: 0.1, repeats: true) { [weak self] _ in
                guard let self, let recorder = self.recorder else { return }
                recorder.updateMeters()
                let db = recorder.averagePower(forChannel: 0)
                self.level = CGFloat(max(0, min(1, (db + 60) / 60)))
            }
        } catch {
            errorMessage = error.localizedDescription
        }
    }

    func stopAndSave() {
        guard let recorder, isRecording else { return }

        recorder.stop()
        meterTimer?.invalidate()
        meterTimer = nil
        isRecording = false
        level = 0

        do {
            let documents = FileManager.default.urls(for: .documentDirectory,
                                                      in: .userDomainMask)[0]
            let destination = documents.appendingPathComponent(recorder.url.lastPathComponent)
            try FileManager.default.moveItem(at: recorder.url, to: destination)
            savedURL = destination
            try? AVAudioSession.sharedInstance().setActive(
                false, options: .notifyOthersOnDeactivation
            )
        } catch {
            errorMessage = error.localizedDescription
        }
        self.recorder = nil
    }
}

