        boolean run = true;

        while (run) {
            System.out.println("-----------------------------");
            System.out.println("1.예금 | 2.출금 | 3.잔고 | 4.종료");
            System.out.println("-----------------------------");
            System.out.print("선택> ");

            String choice = scan.nextLine();

            switch (choice) {
                case "1":
                    System.out.print("예금액>");
                    try {
                        BigInteger amount = new BigInteger(scan.nextLine());
                        if (amount.compareTo(BigInteger.ZERO) > 0) {
                            balance = balance.add(amount);
                        } else {
                            System.out.println("올바른 값을 입력하시오");
                        }
                    } catch (NumberFormatException e) {
                        System.out.println("숫자로 입력하시오");
                    }
                    break;

                case "2":
                    System.out.print("출금액>");
                    try {
                        BigInteger amount = new BigInteger(scan.nextLine());
                        if (amount.compareTo(BigInteger.ZERO) > 0
                                && amount.compareTo(balance) <= 0) {
                            balance = balance.subtract(amount);
                        } else {
                            System.out.println("잔액이 부족합니다 혹은 잘못된 입력입니다");
                        }
                    } catch (NumberFormatException e) {
                        System.out.println("숫자로 입력하시오");
                    }
                    break;

                case "3":
                    System.out.println("잔고>" + balance);
                    break;

                case "4":
                    run = false;
                    break;

                default:
                    System.out.println("1, 2, 3, 4 중 하나로 입력하시오");
            }
        }

        System.out.println("프로그램 종료");
        scan.close();
    }
}
